end
if kq.ice>0 then
local oq=bb.rogueShare(dGd[1886])
lq=lq*(oq+(1-oq)/(1-kq.ice+kq.ice/fb.modFactor(dGd[2015])))
end
if kq.fly>0 then
lq=lq*(1-kq.fly*0.5)
end
if kq.noCC then
lq=lq*0.95
end
if kq.shroud then
lq=lq*0.9
end
if kq.zap then
lq=lq*0.85
end
return lq/kb.weatherK(jq)
end
