function kb.weatherLearn()
if bb.withOthers or#game:GetService(dGd[655]):GetPlayers()>1 then
return
end
local rq=bb.huntWeather or kb.weatherNow()
local sq,tq=bb.pred,bb.calRun
if not rq or type(sq)~=dGd[1751]or type(tq)~=dGd[1751]then
return
end
local function uq(vq,wq)
return type(vq)==dGd[1751]and tonumber(vq[wq]or vq[tostring(wq)])or nil
end
local xq={}
for yq=2,bb.wave()do
local zq,Aq=uq(tq.alive,yq),uq(sq.aliveAt,yq)
if zq and Aq and zq>0 and Aq>0 then
table.insert(xq,zq/Aq)
end
end
if#xq<3 then
return
end
table.sort(xq)
local Bq=xq[math.ceil(#xq/2)]
P.hunt.wk=type(P.hunt.wk)==dGd[1751]and P.hunt.wk or{}
local Cq=P.hunt.wk[tostring(rq)]
