Gq=U.clamp(Gq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(rq),old=Cq}
P.hunt.wk[tostring(rq)]={k=Gq,n=(type(Cq)==dGd[1751]and tonumber(Cq.n)or 0)+1,at=os.time()}
F.log(1,dGd[2016],string.format(dGd[2017],tostring(rq),Bq,tostring(rq),Gq,Eq,P.hunt.wk[tostring(rq)].n))
end
