function jb.gainXp(IQ,JQ)
local KQ,LQ=tonumber(IQ.xp)or 0,jb.xpFor(IQ.unit_id,jb.cap(IQ))
local MQ=math.max(0,LQ-KQ)
if MQ<=0 or(JQ or 0)<=0 then
return 0,0
end
local NQ=math.min(JQ,MQ)
local OQ=jb.base(IQ)
if OQ<=0 then
return 0,NQ
end
return jb.share(IQ.unit_id)*(jb.score(jb.whatIf(IQ,{xp=KQ+NQ}))/OQ-1)*100,NQ
end
