end
function jb.relicWorth(PQ,QQ)
local RQ=QQ._unique_item_data and QQ._unique_item_data._unique_relic_data
if not RQ then
return 0
end
local SQ=N.Items[QQ.item_id]or{}
local TQ,UQ=V.types(PQ.unit_id)
if SQ.main_damage_type and SQ.main_damage_type~=dGd[2461]and SQ.main_damage_type~=UQ then
return 0
end
local VQ,WQ=0,0
for XQ,YQ in pairs(RQ._core_damage_type_buffs or{})do
if TQ[YQ.damage_type]then
VQ=VQ+(tonumber(YQ.mul)or 0)+(tonumber(YQ.add_upg)or 0)*0.01+(tonumber(YQ.pen)or 0)*0.001
WQ=WQ+(tonumber(YQ.crit)or 0)
end
end
VQ=VQ+WQ*0.5
local ZQ=V.rows(PQ.unit_id)
local _Q=ZQ and ZQ[ZQ.max]
local aR=(_Q and tonumber(_Q.cd)or 0)*V.mult(PQ,dGd[1916])
for bR,cR in pairs(RQ._unique_relic_effects or{})do
local dR=type(cR.params)==dGd[1751]and cR.params or{}
if cR.id==dGd[2462]then
local eR=math.min(1,(tonumber(dR.extra_damage)or 0)*aR/math.max(1,tonumber(dR.time_interval)or 40))
local fR=V.DRONES and V.DRONES[PQ.unit_id]
if fR and fR.late and aR>0 then
local gR=1/aR
eR=eR*gR/(gR+(tonumber(fR.max)or 0)*(tonumber(fR.late.dmg)or 0)*(tonumber(fR.hits)or 1)/math.max(0.1,tonumber(fR.late.cd)or 4))
end
VQ=VQ+eR
elseif cR.id==dGd[2463]then
VQ=VQ+(tonumber(dR.dmg_buff)or 0)*0.25
elseif cR.id==dGd[2464]then
VQ=VQ+(tonumber(dR.dmg_buff)or 0)*WQ
elseif cR.id==dGd[2465]then
if TQ.magic then
VQ=0
else
VQ=VQ+(tonumber(dR.dmg_buff)or 0)*0.3
end
elseif cR.id==dGd[2466]then
if TQ.water_damage then
VQ=VQ+0.05
end
end
end
return VQ
end
function jb.relicPlan()
local hR=N.session()
if not hR then
return nil
end
local iR=hR.inventory and hR.inventory.inventory_profile_data or{}
local jR={}
for kR,lR in ipairs(iR.unique_items or{})do
if type(lR)==dGd[1751]and lR.uuid and(N.Items[lR.item_id]or{}).item_group==dGd[2467]then
table.insert(jR,lR)
end
end
local mR={}
for nR,oR in ipairs(V.equipped())do
local pR=oR.data and oR.data.rarity
if not V.isFarm(oR.id)and(pR==dGd[2045]or pR==dGd[2046]or pR==dGd[2459]or pR==dGd[2468])then
local qR=jb.share(oR.id)
if not P.str.share[oR.id]then
qR=math.min(qR,0.15)
end
local rR={}
for sR,tR in ipairs(jR)do
local uR=jb.relicWorth(oR.u,tR)*qR*100
if uR>0.01 then
table.insert(rR,{it=tR,w=uR})
end
end
table.sort(rR,function(vR,wR)
if vR.w~=wR.w then
return vR.w>wR.w
end
return vR.it.uuid<wR.it.uuid
end)
local xR,yR={},{}
for zR,AR in ipairs(rR)do
local BR=yR[AR.it.item_id]or 0
if#xR<6 and BR<((N.Items[AR.it.item_id]or{}).unique_equip and 1 or 2)then
yR[AR.it.item_id]=BR+1
table.insert(xR,AR)
end
end
if oR.u._equipped_relic then
local CR=false
for DR,ER in ipairs(xR)do
if ER.it.uuid==oR.u._equipped_relic then
CR=true
end
end
local FR=not CR and hR.inventory:get_item_by_uuid(oR.u._equipped_relic)
if FR then
table.insert(xR,{it=FR,w=jb.relicWorth(oR.u,FR)*qR*100})
end
end
table.insert(mR,{e=oR,share=qR,opts=xR})
end
end
local GR,HR={},-1
local IR,JR,KR={},{},{}
local function LR(MR,NR)
if MR> #mR then
if NR>HR then
HR=NR
GR=table.clone(IR)
end
return
end
local OR=mR[MR]
IR[OR.e.uuid]=nil
LR(MR+1,NR)
for PR,QR in ipairs(OR.opts)do
local RR=(N.Items[QR.it.item_id]or{}).unique_equip
if not JR[QR.it.uuid]and not(RR and KR[QR.it.item_id])then
JR[QR.it.uuid]=true
if RR then
KR[QR.it.item_id]=true
end
IR[OR.e.uuid]=QR.it.uuid
LR(MR+1,NR+QR.w+(QR.it.uuid==OR.e.u._equipped_relic and 0.01 or 0))
IR[OR.e.uuid]=nil
JR[QR.it.uuid]=nil
if RR then
KR[QR.it.item_id]=nil
end
end
end
end
LR(1,0)
local SR,TR=0,{}
for UR,VR in ipairs(mR)do
local WR=VR.e.u._equipped_relic and hR.inventory:get_item_by_uuid(VR.e.u._equipped_relic)
local XR=WR and jb.relicWorth(VR.e.u,WR)*VR.share*100 or 0
SR=SR+XR
local YR=GR[VR.e.uuid]and hR.inventory:get_item_by_uuid(GR[VR.e.uuid])
local ZR=YR and jb.relicWorth(VR.e.u,YR)*VR.share*100 or 0
table.insert(TR,string.format(dGd[2469],V.name(VR.e.id),WR and(N.Items[WR.item_id]or{}).name or dGd[2056],XR,YR and(N.Items[YR.item_id]or{}).name or dGd[2056],ZR))
end
return GR,HR-SR,TR,mR
end
function jb.relicsApply(_R)
