function jb.feedPlan(eU)
local fU=V.trait(eU)
local gU=fU==dGd[2486]and 1.5 or 1
local hU=math.max(0,jb.xpFor(eU.unit_id,jb.cap(eU))-(tonumber(eU.xp)or 0))
local iU,jU,kU={},0,0
for lU,mU in ipairs(jb.foodHeld())do
local nU=mU.xp*gU
local oU=math.min(mU.n,math.floor((hU-jU)/math.max(1,nU)))
if oU>0 then
iU[mU.id]=oU
jU=jU+oU*nU
kU=kU+oU
end
end
return{feed=iU,planned=jU,n=kU}
end
function jb.run(pU)
local qU=N.session()
local rU=qU and qU.collection:get_unit_by_uuid(pU.uuid)
if not rU then
return
end
if pU.kind==dGd[2480]then
local sU=jb.feedPlan(rU)
local tU,uU,vU=sU.feed,sU.planned,sU.n
if vU==0 then
P.str.feedNote=pU.name..dGd[2487]
