end
local wU,xU=tonumber(rU.xp)or 0,jb.level(rU)
local yU,zU=F.request(dGd[2480],dGd[2488],pU.uuid,tU)
local AU=U.now()
while U.now()-AU<4 and(tonumber((qU.collection:get_unit_by_uuid(pU.uuid)or rU).xp)or 0)<=wU do
task.wait(0.25)
end
local BU=qU.collection:get_unit_by_uuid(pU.uuid)or rU
local CU=(tonumber(BU.xp)or 0)-wU
if CU>0 then
local DU=jb.level(BU)
local EU=DU>xU and string.format(dGd[2482],xU,DU)or string.format(dGd[2483],xU)
cb.add(string.format(dGd[2489],vU,pU.name),vU,dGd[2490],string.format(dGd[2491],U.fmt(CU),EU))
jb.note(string.format(dGd[2492],pU.name,vU,U.fmt(CU),EU,math.abs(CU-uU)>uU*0.1 and string.format(dGd[2493],U.fmt(uU))or dGd[676]))
else
jb.note(string.format(dGd[2494],pU.name,tostring(yU and zU or dGd[2069])))
F.backoff(dGd[2480],600)
end
end
end
