function ab.unitLabSafe(beb)
if O.unitLab==false or type(beb)~=dGd[1751]or not ab.LAB.KINDS[beb.kind]or beb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==dGd[1751]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=dGd[679]then
return false
end
local ceb,deb=pcall(ab.matchOn,beb)
if ceb and deb then
return false
end
local eeb=type(P.unitLab)==dGd[1751]and P.unitLab or{}
if eeb.pauseKey==beb.key and os.time()<(tonumber(eeb.pauseUntil)or 0)then
return false
end
local feb=W.rec(beb.key)
local geb,heb=tonumber(feb.runs)or 0,tonumber(feb.wins)or 0
if beb.kind==dGd[1770]then
local ieb,jeb=pcall(W.infDaily,N.prof(),beb.level,W.infReach(beb.key))
return geb>=3 and ieb and(tonumber(jeb)or 1)<=0
end
return geb>=5 and(tonumber(feb.streak)or 0)==0 and heb/geb>=0.9
end
function ab.unitLab(keb)
if not ab.unitLabSafe(keb)then
return
end
P.unitLab=type(P.unitLab)==dGd[1751]and P.unitLab or{}
local leb=P.unitLab
leb.tried=type(leb.tried)==dGd[1751]and leb.tried or{}
leb.seen=(tonumber(leb.seen)or 0)+1
if leb.seen%ab.LAB.EVERY~=0 then
return
end
local meb=N.session()
local neb=V.equipped()
if not meb or#neb<2 then
return
end
local oeb={}
for peb,qeb in ipairs(neb)do
oeb[qeb.uuid]=true
oeb[qeb.id]=true
end
local reb,seb,teb
for ueb,veb in pairs(meb.profile_data.collection.owned_units)do
local web=veb.unit_id
if not oeb[ueb]and not oeb[web]and N.Units[web]and not V.isFarm(web)and not V.allyBuff(web)and os.time()-(tonumber(leb.tried[web])or 0)>ab.LAB.AGAIN then
local xeb=ab.unitEvidence(web)
if xeb<ab.LAB.MIN_EVIDENCE then
local yeb=meb.collection:get_unit_by_uuid(ueb)or veb
local zeb=jb.score(yeb)
if zeb>0 and(not reb or xeb<seb or(xeb==seb and zeb>teb))then
reb,seb,teb={uuid=ueb,id=web,u=yeb},xeb,zeb
end
end
end
end
if not reb then
return
end
local Aeb,Beb
for Ceb,Deb in ipairs(neb)do
if not V.isFarm(Deb.id)and not V.allyBuff(Deb.id)and Deb.uuid~=O.evolveUnit then
local Eeb=jb.score(Deb.u)
if not Aeb or Eeb<Beb then
Aeb,Beb=Deb,Eeb
end
end
end
if not Aeb then
return
end
leb.tried[reb.id]=os.time()
local Feb=0
for Geb in pairs(leb.tried)do
Feb=Feb+1
if Feb>300 then
leb.tried[Geb]=nil
end
end
local Heb,Ieb=fb.levelFor(keb)
if not Heb then
return
end
local Jeb=fb.info(Heb,keb.key,Ieb,keb.mod or W.ldMod(Heb)or W.levelMod(keb.level))
local Keb={}
for Leb,Meb in ipairs(neb)do
table.insert(Keb,Meb.uuid==Aeb.uuid and reb.u or Meb.u)
end
local Neb,Oeb=pcall(fb.run,Jeb,fb.teamFrom(Keb,Jeb.map),{hpMul=1.1})
local Peb=Neb and type(Oeb)==dGd[1751]and(Oeb.won or(Jeb.infinite and(tonumber(Oeb.wave)or 0)>=0.8*W.infReach(keb.key)))
if not Peb then
F.log(2,dGd[2976],string.format(dGd[2977],V.name(reb.id),keb.label))
return
end
local Qeb={}
for Reb,Seb in ipairs(neb)do
table.insert(Qeb,Seb.uuid==Aeb.uuid and reb.uuid or Seb.uuid)
end
if ab.equipTeam(Qeb,dGd[2978]..V.name(reb.id))then
leb.now={id=reb.id,out=Aeb.id,key=keb.key,at=os.time(),ev=seb}
F.log(1,dGd[2976],string.format(dGd[2979],V.name(reb.id),V.name(Aeb.id),keb.label,seb))
F.saveNow()
end
end
