function eb.upgradeGain(Aib,Bib,Cib,Dib,Eib,Fib)
local Gib,Hib=Bib[Cib],Bib[Cib+1]
local Iib=(Gib.cd>0 and Gib.damage/Gib.cd or 0)
local Jib=(Hib.cd>0 and Hib.damage/Hib.cd or 0)*V.aoe(Hib.atk,Hib.range)/math.max(0.3,V.aoe(Gib.atk,Gib.range))
local Kib=Iib>0 and Aib*(Jib/Iib-1)or(Fib or 0)
