for Eqb=1,fb.BINS do
local Fqb,Gqb={},math.huge
for Hqb in pairs(xqb[Eqb]or{})do
table.insert(Fqb,Hqb)
end
for Iqb=1,#Fqb do
for Jqb=Iqb+1,#Fqb do
for Kqb,Lqb in ipairs(xqb[Eqb][Fqb[Iqb]])do
for Mqb,Nqb in ipairs(xqb[Eqb][Fqb[Jqb]])do
local Oqb,Pqb=Lqb.X-Nqb.X,Lqb.Z-Nqb.Z
local Qqb=Oqb*Oqb+Pqb*Pqb
if Qqb<Gqb then
Gqb=Qqb
end
end
end
end
end
if#Fqb>=2 then
yqb=true
end
Dqb[Eqb]=Gqb<math.huge and math.floor(math.sqrt(Gqb)+0.5)or 9999
end
return yqb and Dqb or nil
end
function fb.mapSep(Rqb)
