end
for brb,crb in ipairs(Yqb or{})do
if crb~=Tqb and crb.mask and not(crb.e and crb.e.farm)and not crb.buff then
for drb,erb in ipairs(Wqb)do
local frb=crb.mask.lanes and crb.mask.lanes[erb]
for grb=1,fb.BINS do
if(frb and frb[grb])or(not crb.mask.lanes and crb.mask[grb])then
Zqb[erb]=Zqb[erb]+1
end
end
end
end
end
local hrb=Wqb[1]
for irb,jrb in ipairs(Wqb)do
if Zqb[jrb]<Zqb[hrb]then
hrb=jrb
end
end
Tqb.laneOne=hrb
end
local krb={lanes={}}
for lrb=1,fb.BINS do
krb[lrb]=Uqb[lrb]==true
end
for mrb,nrb in ipairs(Wqb)do
local orb={}
for prb=1,fb.BINS do
orb[prb]=krb[prb]and(nrb==Tqb.laneOne or(tonumber(Xqb[prb])or math.huge)<=Vqb)
