if Arb then
for Brb=fb.BINS,1,-1 do
if Arb[Brb]then
if Brb/fb.BINS>trb[zrb]then
trb[zrb]=Brb/fb.BINS
end
break
end
end
end
end
end
end
local Crb,Drb
for Erb,Frb in ipairs(qrb or{})do
