fb.DMG_PRIOR_RUNS=6
function fb.dmgAll()
local Tsb=fb._dmgAll
if Tsb and os.clock()-Tsb.t<60 then
return Tsb.v
end
local Usb,Vsb={},{}
for Wsb,Xsb in pairs(P.simCal)do
local Ysb=Wsb~=dGd[1776]and not tostring(Wsb):find(dGd[3124],1,true)and type(Xsb)==dGd[1751]and type(Xsb.dmgK)==dGd[1751]and Xsb.dmgK or nil
for Zsb=1,#fb.DMG_BANDS do
local _sb=Ysb and Ysb[tostring(Zsb)]
local atb,btb=type(_sb)==dGd[1751]and tonumber(_sb.k)or nil,type(_sb)==dGd[1751]and tonumber(_sb.n)or 0
if atb and atb>0 and btb>0 then
Usb[Zsb]=(Usb[Zsb]or 0)+btb*math.log(atb)
Vsb[Zsb]=(Vsb[Zsb]or 0)+btb
end
end
end
local ctb={}
for dtb,etb in pairs(Usb)do
ctb[tostring(dtb)]={k=math.exp(etb/(Vsb[dtb]+fb.DMG_PRIOR_RUNS)),n=0}
end
fb._dmgAll={t=os.clock(),v=ctb}
return ctb
end
function fb.dmgHive(ftb)
