if type(itb)~=dGd[1751]then
return nil
end
local jtb={}
for ktb,ltb in pairs(itb)do
if type(ltb)==dGd[1751]and tonumber(ltb[1])and((tonumber(ltb[2])or 0)>=2 or(tonumber(ltb[3])or 0)>=4)then
jtb[tostring(ktb)]={k=U.clamp(tonumber(ltb[1]),fb.DMG_MIN,fb.DMG_MAX),n=0,hive=true}
end
end
return next(jtb)and jtb or nil
