function fb.dmgK(mtb,ntb)
local otb=mtb._dk
if not otb then
otb={}
mtb._dk=otb
end
local ptb=otb[ntb]
if ptb then
return ptb
end
ptb=1
local qtb=mtb.dmgK
if type(qtb)~=dGd[1751]or next(qtb)==nil then
qtb=fb.dmgHive(mtb.key)or fb.dmgAll()
end
if type(qtb)==dGd[1751]then
local rtb,stb=fb.dmgBand(math.max(1,ntb)),math.huge
for ttb=1,#fb.DMG_BANDS do
local utb=qtb[tostring(ttb)]
local vtb=type(utb)==dGd[1751]and tonumber(utb.k)or nil
if vtb and math.abs(ttb-rtb)<stb then
ptb,stb=vtb,math.abs(ttb-rtb)
end
end
end
ptb=ptb*(tonumber(mtb.dmgMul)or 1)
otb[ntb]=ptb
return ptb
