fb.DMG_SOLVE_LO,fb.DMG_SOLVE_HI,fb.DMG_SOLVE_TRIES=0.1,3,6
function fb.dmgSolve(wtb,xtb,ytb,ztb,Atb)
local function Btb(Ctb)
local Dtb=table.clone(wtb)
Dtb.dmgMul,Dtb._dk=Ctb,nil
local Etb,Ftb=pcall(fb.runRaw,Dtb,xtb,ytb)
if not(Etb and type(Ftb)==dGd[1751])then
return nil
end
if Atb then
return Ftb.won and 1 or-1
end
if Ftb.won then
return 1
end
return(tonumber(Ftb.wave)or 0)-ztb
end
local Gtb,Htb=math.log(fb.DMG_SOLVE_LO),math.log(fb.DMG_SOLVE_HI)
local Itb=Btb(fb.DMG_SOLVE_LO)
if not Itb then
return nil
end
if Itb>=0 then
return fb.DMG_SOLVE_LO
end
local Jtb=Btb(fb.DMG_SOLVE_HI)
if not Jtb then
return nil
end
if Jtb<0 then
return fb.DMG_SOLVE_HI
end
for Ktb=1,fb.DMG_SOLVE_TRIES do
task.wait()
local Ltb=(Gtb+Htb)/2
local Mtb=Btb(math.exp(Ltb))
if not Mtb then
return nil
end
if Mtb>=0 then
Htb=Ltb
else
Gtb=Ltb
end
end
return math.exp(Htb)
end
function fb.mid(Ntb)
