return type(cub)==dGd[1751]and tonumber(cub[dub]or cub[tostring(dub)])or nil
end
local eub=fb.cal(Ttb)
local fub=aub and dGd[3140]or dGd[3141]
local gub={}
for hub,iub in pairs(type(eub.dmgK)==dGd[1751]and eub.dmgK or{})do
gub[hub]=iub
end
local jub=fb.dmgBand(math.max(1,Ytb))
for kub=6,Ytb do
local lub,mub=bub(Ztb,kub)or 0,bub(_tb,kub)or 0
local nub=0
for oub,pub in ipairs((fb.wave(Utb,kub)))do
nub=nub+(tonumber(pub.hp)or 0)+(tonumber(pub.bar)or 0)
