local function qub(rub)
local tub=gub[tostring(rub)]
if type(tub)==dGd[1751]and(tonumber(tub.n)or 0)>0 then
return tonumber(tub.n)
end
local uub,vub=0,math.huge
for wub=1,#fb.DMG_BANDS do
local xub=gub[tostring(wub)]
if type(xub)==dGd[1751]and tonumber(xub.k)and(tonumber(xub.n)or 0)>0 and math.abs(wub-rub)<vub then
uub,vub=tonumber(xub.n),math.abs(wub-rub)
end
end
return uub
end
local yub=fb.dmgBand(math.max(1,Ytb))
local zub={}
for Aub=1,yub do
zub[Aub]=qub(Aub)
end
local Bub={}
local Cub=Xtb^(1-fb.UNIT_SPLIT)
for Dub=1,yub do
local Eub=Dub==1 and 1 or fb.DMG_BANDS[Dub-1]+1
local Fub=type(gub[tostring(Dub)])==dGd[1751]and gub[tostring(Dub)]or nil
local Gub=(Fub and tonumber(Fub.k))or fb.dmgK(Utb,Eub)
local Hub=zub[Dub]
if Dub<jub then
if not Fub then
gub[tostring(Dub)]={k=Gub,n=0,at=os.time(),src=dGd[3142]}
end
else
local Iub=Hub==0 and 1 or math.max(0.5,1/(Hub+1))
local Jub=U.clamp(Gub*Cub^Iub,fb.DMG_MIN,fb.DMG_MAX)
gub[tostring(Dub)]={k=Jub,n=Hub+1,at=os.time(),src=dGd[1777]}
table.insert(Bub,string.format(dGd[3143],fb.dmgBandName(Dub),Jub,Gub))
end
end
local Kub=table.clone(Utb)
Kub.dmgMul,Kub._dk=Xtb,nil
local Lub={}
for Mub,Nub in pairs(Wtb or{})do
Lub[Mub]=Nub
end
Lub.dealt={}
local Oub=pcall(fb.runRaw,Kub,Vtb,Lub)
local Pub={}
for Qub,Rub in pairs(type(eub[fub])==dGd[1751]and eub[fub]or{})do
Pub[Qub]=Rub
end
if Oub then
local Sub,Tub={},0
for Uub,Vub in ipairs(Vtb)do
if not Vub.farm and not Sub[Vub.id]then
local Wub=(tonumber(Lub.dealt[V.name(Vub.id)])or 0)+((V.DRONES and V.DRONES[Vub.id])and(tonumber(Lub.dealt.drones)or 0)or 0)
Sub[Vub.id]={e=Vub,d=Wub}
Tub=Tub+Wub
end
end
local Xub=0
for Yub,Zub in pairs(Sub)do
Zub.s=Tub>0 and Zub.d/Tub or 0
if Zub.s>=fb.UNIT_SHARE_MIN then
Xub=Xub+Zub.s*Zub.s
