local hvb=U.clamp(fvb*math.exp(gvb),fb.UNIT_MIN,fb.UNIT_MAX)
Pub[avb]={k=hvb,n=dvb+1,at=os.time()}
table.insert(_ub,{s=bvb.s,t=string.format(dGd[3144],V.name(avb),hvb,aub and dGd[3145]or dGd[3146],math.floor(bvb.s*100+0.5),fvb)})
end
end
table.sort(_ub,function(ivb,jvb)
return ivb.s>jvb.s
end)
for kvb,lvb in ipairs(_ub)do
table.insert(Bub,lvb.t)
end
end
end
eub.dmgK,eub[fub]=gub,Pub
fb._dmgAll=nil
