end
fb.SHARE_FLOOR,fb.SHARE_STEP=0.03,0.5
function fb.shareLearn()
if bb.withOthers or bb.joinedMid or bb.random or bb.trialId or bb.stopping or#game:GetService(dGd[655]):GetPlayers()>1 then
return
end
local mvb=bb.info
if type(mvb)~=dGd[1751]or type(bb.predUnits)~=dGd[1751]or#bb.predUnits==0 or not bb.key then
return
end
local nvb=bb.damageShares()
if not nvb then
return
end
local ovb=fb.teamFrom(bb.predUnits,mvb.map)
local pvb={}
for qvb,rvb in pairs(bb.predOpt or{hpMul=1})do
pvb[qvb]=rvb
end
pvb.dealt={}
if not pcall(fb.runRaw,mvb,ovb,pvb)then
return
end
local svb,tvb={},0
for uvb,vvb in ipairs(ovb)do
if not vvb.farm and not svb[vvb.id]then
local wvb=(tonumber(pvb.dealt[V.name(vvb.id)])or 0)+((V.DRONES and V.DRONES[vvb.id])and(tonumber(pvb.dealt.drones)or 0)or 0)
svb[vvb.id]={e=vvb,d=wvb}
tvb=tvb+wvb
end
end
if tvb<=0 then
return
end
local xvb=fb.cal(bb.key)
local yvb=bb.killZone()and true or false
local zvb=yvb and dGd[3140]or dGd[3141]
local Avb={}
for Bvb,Cvb in pairs(type(xvb[zvb])==dGd[1751]and xvb[zvb]or{})do
Avb[Bvb]=Cvb
end
local Dvb,Evb=0,0
for Fvb,Gvb in pairs(svb)do
Gvb.p,Gvb.r=Gvb.d/tvb,tonumber(nvb[Fvb])or 0
if Gvb.p>=fb.SHARE_FLOOR or Gvb.r>=fb.SHARE_FLOOR then
local Hvb=type(Avb[Fvb])==dGd[1751]and Avb[Fvb]or nil
local Ivb=Hvb and tonumber(Hvb.sn)or 0
Gvb.step=U.clamp(fb.SHARE_STEP*math.max(0.5,1/(Ivb+1))*math.log((Gvb.r+fb.SHARE_FLOOR)/(Gvb.p+fb.SHARE_FLOOR)),-math.log(2),math.log(2))
Gvb.old,Gvb.sn=Hvb,Ivb
Dvb,Evb=Dvb+Gvb.step,Evb+1
end
end
if Evb<2 then
return
end
local Jvb=Dvb/Evb
local Kvb={}
bb.shareRows={}
for Lvb,Mvb in pairs(svb)do
if Mvb.step then
bb.shareRows[Lvb]={r=Mvb.r,p=Mvb.p}
end
end
for Nvb,Ovb in pairs(svb)do
if Ovb.step then
local Pvb=(Ovb.old and tonumber(Ovb.old.k))or fb.unitK(mvb,Ovb.e,yvb)
local Qvb=U.clamp(Pvb*math.exp(Ovb.step-Jvb),fb.UNIT_MIN,fb.UNIT_MAX)
Avb[Nvb]={k=Qvb,n=Ovb.old and tonumber(Ovb.old.n)or 0,sn=Ovb.sn+1,at=os.time()}
if math.abs(Qvb/Pvb-1)>=0.05 then
table.insert(Kvb,{p=Ovb.p,t=string.format(dGd[3147],V.name(Nvb),math.floor(Ovb.r*100+0.5),math.floor(Ovb.p*100+0.5),Qvb,Pvb)})
end
end
end
xvb[zvb]=Avb
if#Kvb==0 then
return
end
table.sort(Kvb,function(Rvb,Svb)
return Rvb.p>Svb.p
end)
local Tvb={}
for Uvb,Vvb in ipairs(Kvb)do
table.insert(Tvb,Vvb.t)
end
local Wvb,Xvb=pcall(bb.label)
F.log(1,dGd[3148],string.format(dGd[3149],tostring(Wvb and Xvb or bb.key),yvb and dGd[3145]or dGd[3146],table.concat(Tvb,dGd[1982])))
end
function fb.dmgLearn(Yvb)
if bb.withOthers or bb.joinedMid or bb.random or bb.trialId or bb.stopping or bb.roomKUp or#game:GetService(dGd[655]):GetPlayers()>1 then
