function ib.sim(mRb,nRb,oRb)
if not O.sim or type(mRb.r._l)~=dGd[1751]then
return nil
end
local pRb=tostring(mRb.r._r or(mRb.d..dGd[1877]..mRb.choice))..(nRb and(dGd[1911]..tostring(nRb))or dGd[676])..(oRb and dGd[3338]or dGd[676])
local qRb=ib.data()
local rRb=ib.fx(qRb,ib.roomCurse(mRb.r),nRb)
local sRb=W.teamSig()..dGd[1910]..ib.fxText(rRb)..(O.killZone~=false and dGd[3339]or dGd[676])..(bb.forcedWay()and(dGd[1910]..bb.forcedWay())or dGd[676])
local tRb=P.dg.sim[pRb]
if tRb and tRb.sig==sRb then
return not tRb.none and tRb or nil
end
local uRb={}
for vRb,wRb in ipairs(V.equipped())do
table.insert(uRb,wRb.u)
end
if#uRb==0 then
return nil
end
local xRb=fb.applyFx(fb.info(fb.slim(mRb.r._l),dGd[2191],nil,ib.mod(mRb.r._l)),rRb)
ib.applyK(xRb,mRb.r._r)
if oRb then
xRb.zone=false
end
local yRb=fb.wave(xRb,1,true)
if#yRb==0 then
tRb={none=true,sig=sRb,at=os.time()}
else
local zRb=fb.evaluate(xRb,fb.teamFrom(uRb,xRb.map))
tRb={p=zRb.p,wave=zRb.wave,won=zRb.won,total=xRb.total,margin=zRb.margin,sig=sRb,at=os.time(),zone=xRb.zone~=false or nil}
end
P.dg.sim[pRb]=tRb
if U.count(P.dg.sim)>60 then
local ARb,BRb
for CRb,DRb in pairs(P.dg.sim)do
if not BRb or(DRb.at or 0)<BRb then
ARb,BRb=CRb,DRb.at or 0
end
end
P.dg.sim[ARb]=nil
end
F.saveSoon()
return not tRb.none and tRb or nil
end
function ib.winP(ERb)
local FRb=tostring(math.min(4,math.max(1,math.ceil(ERb.d/5))))
local GRb=P.dg.depth[FRb]or{runs=0,wins=0}
local HRb=U.clamp(0.95-0.015*ERb.d,0.5,0.95)
local IRb=((tonumber(GRb.wins)or 0)+HRb*2)/((tonumber(GRb.runs)or 0)+2)
local JRb,KRb=pcall(ib.sim,ERb)
if JRb and KRb and KRb.p then
local LRb,MRb=pcall(fb.styleP,KRb,KRb.zone==false and dGd[3187]or(KRb.zone and dGd[3127]or nil))
IRb=(IRb*2+(LRb and MRb or KRb.p))/3
end
return IRb,JRb and KRb or nil
end
function ib.hopeless(NRb)
return NRb~=nil and NRb.won==false and(tonumber(NRb.p)or 1)<=0.05
end
function ib.stake(ORb)
