end
function ib.curseOk(XRb,YRb,ZRb,_Rb,aSb)
local bSb=tostring((ib.item(XRb)or{}).name or XRb)
local cSb,dSb,eSb=ib.curseBar(YRb,ZRb)
if cSb>0.2 and ib.blindCurse(YRb,XRb)then
return false,string.format(dGd[3343],bSb,eSb)
end
local function fSb(gSb)
return gSb==nil or(tonumber(gSb.p)or 1)>=cSb
end
if _Rb then
local hSb,iSb=pcall(ib.sim,_Rb,nil,true)
if hSb and not fSb(iSb)then
return false,string.format(dGd[3344],bSb,(dSb:gsub(dGd[3345],dGd[3346])),tostring(iSb.margin or dGd[2025]))
end
end
if#aSb==0 then
return true
end
local jSb
for kSb,lSb in ipairs(aSb)do
local mSb,nSb=pcall(ib.sim,lSb,XRb,true)
if not mSb or fSb(nSb)then
return true
end
if not jSb or(tonumber(nSb.p)or 0)>(tonumber(jSb.p)or 0)then
jSb=nSb
end
end
return false,string.format(dGd[3347],bSb,dSb,tostring(jSb and jSb.margin or dGd[2025]))
end
function ib.curseGate(oSb,pSb)
