return ib.curseOk(qSb,pSb,oSb.d,oSb,ib.after(pSb,oSb.choice))
end
function ib.payValue()
local rSb,sSb=0,0
for tSb,uSb in ipairs(P.dg.pay or{})do
if type(uSb.items)==dGd[1751]then
local vSb=tonumber(uSb.gems)or 0
for wSb,xSb in pairs(uSb.items)do
if(tonumber(xSb)or 0)>0 then
vSb=vSb+W.itemValue(wSb,xSb)
end
end
rSb,sSb=rSb+vSb,sSb+1
end
end
if sSb<5 then
return nil
end
return rSb/sSb*0.7
end
function ib.pick(ySb)
local zSb,ASb=ib.curses(ySb),ib.lives(ySb)
local BSb=ib.res(ySb)
local CSb=ib.rooms(ySb)
local DSb={}
for ESb,FSb in ipairs(CSb)do
table.insert(DSb,tostring(FSb.r._r))
end
local GSb=table.concat(DSb,dGd[2456])..string.format(dGd[3348],ASb,BSb,zSb,W.teamSig())
if ib._pick and ib._pick.sig==GSb then
return ib._pick.x
end
local HSb,ISb
for JSb,KSb in ipairs(CSb)do
local LSb=ib.roomValue(KSb,BSb)
local MSb,NSb
for OSb,PSb in ipairs(ib.after(ySb,KSb.choice))do
local QSb=ib.roomValue(PSb,BSb)
if not MSb or QSb>MSb then
MSb,NSb=QSb,PSb
end
end
local RSb,SSb=ib.winP(KSb)
local TSb=1-(1-RSb)^math.max(1,ASb)
local USb=ASb>=3 and 1 or(ASb==2 and 2 or 6)
KSb.p,KSb.sim,KSb.value,KSb.nextValue,KSb.nextRoom=RSb,SSb,LSb,MSb or 0,NSb
KSb.score=TSb*(LSb+0.6*(MSb or 0))-(1-RSb)*USb
local VSb,WSb,XSb=pcall(ib.curseGate,KSb,ySb)
if VSb and not WSb then
KSb.blocked=XSb
end
if not KSb.blocked and(not HSb or KSb.score>HSb.score)then
HSb=KSb
end
if not ISb or KSb.score>ISb.score then
ISb=KSb
end
end
HSb=HSb or ISb
ib._pick={sig=GSb,x=HSb,rooms=CSb}
return HSb
end
