if type(BTb)==dGd[662]and ib.item(BTb)then
table.insert(yTb,{key=zTb,id=BTb,cost=CTb or tonumber(ib.item(BTb).cost)or 0,bought=type(ATb)==dGd[1751]and(ATb.bought or ATb.sold or ATb.purchased)or nil})
end
end
if#yTb==0 and not xTb then
