function ib.buy(FTb)
local GTb=ib.res(ib.data())
local HTb={}
if P.dg.buyArg==dGd[3095]then
HTb={FTb.id,FTb.key}
else
HTb={FTb.key,FTb.id}
end
if HTb[1]==HTb[2]then
HTb[2]=nil
end
for ITb,JTb in ipairs(HTb)do
local KTb,LTb=F.request(dGd[3357],dGd[3358],JTb)
local MTb=U.now()
while U.now()-MTb<3 and ib.res(ib.data())>=GTb do
task.wait(0.25)
end
if ib.res(ib.data())<GTb then
P.dg.buyArg=(JTb==FTb.id and FTb.id~=FTb.key)and dGd[3095]or dGd[3359]
return true
end
if not KTb then
break
end
end
