function bb.lookAt(Hnc)
local Inc,Jnc=math.huge,nil
for Knc,Lnc in ipairs(bb.samples)do
local Mnc=(U.flat(Lnc.pos)-U.flat(Hnc)).Magnitude
if Mnc<Inc then
Inc,Jnc=Mnc,Lnc.pos
end
end
local Nnc=Jnc and U.flat(Jnc-Hnc)or Vector3 .new(0,0,-1)
return Nnc.Magnitude>0.01 and Nnc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(Onc,Pnc)
local Qnc=V.isFarm(Onc.id)
local Rnc,Snc=bb.bestSpot(Onc,Qnc or(bb.random and V.idol(Onc.id)),(bb.trainee~=nil and Onc.uuid==bb.trainee)or V.ENTRY[Onc.id]==true or(bb.studyEntry==true and Onc.id==bb.trialId))
if not Rnc then
bb.noSpot[Onc.uuid]=(bb.noSpot[Onc.uuid]or 0)+1
F.status(dGd[3579],dGd[3668]..V.name(Onc.id))
return false
end
local Tnc=bb.money()
local Unc,Vnc=F.request(dGd[3669],dGd[3670],Onc.uuid,N.Util.CFramePLV(Rnc,bb.lookAt(Rnc)))
if Unc and Vnc then
bb.spent=bb.spent+(Onc.data.cost or 0)
table.insert(bb.actions,string.format(dGd[3671],V.name(Onc.id)))
F.log(1,dGd[3585],string.format(dGd[3672],V.name(Onc.id),bb.spotKey(Rnc),Snc,Pnc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=Onc.id,x=math.floor(Rnc.X),z=math.floor(Rnc.Z),cover=math.floor((Snc or 0)+0.5),why=tostring(Pnc):sub(1,90)})
F.status(dGd[3579],string.format(dGd[3673],V.name(Onc.id),Pnc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[Onc.uuid]=(bb.placedAt[Onc.uuid]or 0)+1
return true
end
if Tnc>=(Onc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[Onc.uuid]=(bb.placeFail[Onc.uuid]or 0)+1
if bb.placeFail[Onc.uuid]>=2 then
bb.noSpot[Onc.uuid]=3
F.log(1,dGd[3585],string.format(dGd[3674],V.name(Onc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if Unc and Tnc>=(Onc.data.cost or 0)and not bb.random then
local Wnc=bb.spotKey(Rnc)
bb.refused[Wnc]=true
local Xnc=bb.mapKey()
P.blocked[Xnc]=P.blocked[Xnc]or{}
if not bb.refusedRun[Wnc]then
P.blocked[Xnc][Wnc]=(tonumber(P.blocked[Xnc][Wnc])or 0)+1
bb.refusedRun[Wnc]=true
end
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[Onc.uuid]=(bb.unitRefusals[Onc.uuid]or 0)+1
if bb.unitRefusals[Onc.uuid]>=3 then
local Ync=math.max(1,bb.count(Onc.uuid))
if P.caps[Onc.uuid]~=Ync then
P.caps[Onc.uuid]=Ync
F.log(1,dGd[3585],string.format(dGd[3675],V.name(Onc.id),Ync))
end
end
F.log(2,dGd[3585],dGd[3676]..Wnc..dGd[2394]..V.name(Onc.id))
F.saveSoon()
end
return false
end
