function bb.measure()
local foc,goc=bb.calRun,bb.info
if not(foc and goc)then
return
end
pcall(bb.sampleHelpers)
local hoc=U.now()
local ioc=bb.wave()
local joc=bb.money()
if not foc.start and joc>0 and#bb.mine==0 then
foc.start=joc
end
if ioc~=foc.lastW then
if bb.trialId and ioc>0 then
bb.trialTrace=bb.trialTrace or{}
local koc,loc,moc,noc=0,{},0,0
for ooc,poc in ipairs(bb.mine)do
local qoc=poc._stats
if qoc.id.Value==bb.trialId then
koc=koc+1
table.insert(loc,tostring(qoc.upgrade.Value))
elseif not V.isFarm(qoc.id.Value)then
noc=noc+1
end
end
pcall(bb.sampleHelpers,true)
for roc,soc in pairs(bb.ownDealt)do
if soc.id==bb.trialId then
moc=moc+soc.v
end
end
local toc=0
for uoc,voc in pairs(bb.helperDealt)do
if voc.owner==bb.trialId then
toc=toc+voc.v
end
end
table.insert(bb.trialTrace,string.format(dGd[3678],ioc,hoc-(bb.startT or hoc),joc,table.concat(loc,dGd[2456]),noc,moc+toc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[ioc-1]or 0,bb.teamDps or 0))
end
if foc.lastW and foc.lastW>0 and foc.lastWT then
table.insert(foc.waveSec,hoc-foc.lastWT)
end
if foc.paidT and ioc>0 and hoc-foc.paidT<15 then
table.insert(foc.skip,hoc-foc.paidT)
end
foc.paidT=nil
if ioc>0 then
foc.alive[tostring(ioc)]=bb.hpAliveRaw or 0
end
foc.lastW,foc.lastWT=ioc,hoc
end
local woc=workspace:FindFirstChild(dGd[3679])
if woc and ioc>0 then
foc.timer[tostring(ioc)]=math.max(foc.timer[tostring(ioc)]or 0,tonumber(woc.Value)or 0)
end
local xoc=joc-(bb.lastMoneyR or joc)
bb.lastMoneyR=joc
bb.incomeLog=bb.incomeLog or{}
if xoc>0 then
table.insert(bb.incomeLog,{t=hoc,y=xoc})
end
while bb.incomeLog[1]and hoc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local yoc=0
for zoc,Aoc in ipairs(bb.incomeLog)do
yoc=yoc+Aoc.y
end
local Boc=math.min(30,hoc-(bb.startT or hoc))
bb.incomeRate=Boc>=8 and yoc/Boc or nil
for Coc,Doc in ipairs(bb.enemies)do
local Eoc=Doc.m
local Foc=bb.track[Eoc]
if not Foc then
local Goc=Eoc._stats
local Hoc=Eoc:FindFirstChildOfClass(dGd[3504])
local Ioc=goc.cfgById[Goc.id.Value]
local Joc=Ioc and fb.baseStats(goc,Ioc)
if Hoc and Joc and ioc>0 then
local Koc=Joc*goc.hpRaw*fb.waveScale(goc,ioc,goc.list[ioc])
if Koc>0 and Hoc.MaxHealth>0 then
table.insert(foc.hp,Hoc.MaxHealth/Koc)
end
end
bb.track[Eoc]={t=hoc,p=Doc.prog,sp=(Goc:FindFirstChild(dGd[3680])and tonumber(Goc.speed.Value))or 1}
if Hoc and Hoc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+Hoc.MaxHealth
end
if ioc>0 then
foc.spawn[tostring(ioc)]=(foc.spawn[tostring(ioc)]or 0)+1
foc.spawnLast[tostring(ioc)]=hoc-(foc.lastWT or hoc)
end
elseif not Foc.done and hoc-Foc.t>=15 then
Foc.done=true
local Loc=(Doc.prog-Foc.p)/(hoc-Foc.t)/math.max(0.1,Foc.sp)
if Loc>0.001 and Doc.prog<0.95 then
table.insert(foc.walk,Loc)
end
end
end
local Moc=0
for Noc,Ooc in ipairs(bb.mine)do
local Poc=Ooc._stats:FindFirstChild(dGd[3681])
if Poc then
Moc=Moc+Poc.Value
end
end
foc.potSum=foc.potSum or 0
if foc.lastDealtT then
local Qoc=hoc-foc.lastDealtT
local Roc=0
foc.potBy=foc.potBy or{}
for Soc,Toc in ipairs(bb.mine)do
local Uoc=Toc._stats
local Voc=Uoc.id.Value
if not V.isFarm(Voc)and Uoc:FindFirstChild(dGd[3682])and Uoc.target.Value~=nil then
local Woc,Xoc=pcall(bb.liveDps,Toc,Voc)
if Woc and Xoc then
Roc=Roc+Xoc*Qoc
local Yoc=Xoc/math.max(0.5,V.nudge(Voc))
local Zoc,_oc=pcall(function()
return V.passive(Voc).mark
end)
if Zoc and _oc and Uoc:FindFirstChild(dGd[1915])then
Yoc=Yoc+(tonumber(_oc.dot)or 0)*Uoc.damage.Value
end
foc.potBy[Voc]=(foc.potBy[Voc]or 0)+Yoc*Qoc
end
end
end
foc.potWin=(foc.potWin or 0)+Roc
if hoc-(foc.winT or hoc)>=5 then
local apc=Moc-(foc.winDealt or Moc)
if foc.potWin>0 and apc>=0 then
foc.dealtSum=(foc.dealtSum or 0)+apc
foc.potSum=foc.potSum+foc.potWin
end
foc.winT,foc.winDealt,foc.potWin=hoc,Moc,0
end
end
if not foc.winT then
foc.winT,foc.winDealt=hoc,Moc
end
foc.lastDealtT=hoc
if ioc~=foc.dpsW and ioc>0 then
foc.dpsAt[tostring(ioc)]=bb.teamDps or 0
foc.dpsW=ioc
end
local bpc=math.min(1,hoc-(foc.densT or hoc))
foc.densT=hoc
for cpc,dpc in ipairs(bb.enemies)do
local epc=math.min(fb.BINS,math.floor(dpc.prog*fb.BINS)+1)
foc.dens[epc]=(foc.dens[epc]or 0)+bpc
end
local fpc=workspace._BASES.player:FindFirstChild(dGd[3683])
local gpc=fpc and fpc:FindFirstChild(dGd[3684])
local hpc=gpc and gpc:FindFirstChildOfClass(dGd[3504])
if hpc then
foc.baseHp=math.max(foc.baseHp or 0,hpc.MaxHealth)
local ipc=0
for jpc,kpc in ipairs(bb.enemies)do
if kpc.prog>=0.97 then
local lpc=kpc.m:FindFirstChildOfClass(dGd[3504])
ipc=ipc+(lpc and lpc.MaxHealth or kpc.hp)
end
end
if foc.lastBase and hpc.Health<foc.lastBase and ipc>0 and foc.lastBaseT then
table.insert(foc.baseRel,(foc.lastBase-hpc.Health)/math.max(0.1,hoc-foc.lastBaseT)/ipc)
end
foc.lastBase,foc.lastBaseT=hpc.Health,hoc
end
end
function bb.recordMap()
