if sBc.owner and V.SUMMONER[sBc.owner]then
oBc[sBc.owner]=(oBc[sBc.owner]or 0)+(tonumber(sBc.v)or 0)
end
end
local tBc,uBc=0,0
for vBc,wBc in pairs(nBc)do
