if(tonumber(ABc.v)or 0)<3 then
ABc.eff,ABc.v=(tonumber(ABc.eff)or 1)*V.effRescale(yBc),3
end
local BBc=math.max(0.02,0.25*math.sqrt(30/(30+ABc.n)))
