local IBc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(HBc.n)or 0))))
HBc.eff=(tonumber(HBc.n)or 0)==0 and GBc or((tonumber(HBc.eff)or GBc)+(GBc-(tonumber(HBc.eff)or GBc))*IBc)
HBc.n=(tonumber(HBc.n)or 0)+1
EBc[FBc]=HBc
end
EBc._at=os.time()
P.mapLearn[DBc]=EBc
if U.count(P.mapLearn)>80 then
local JBc,KBc
for LBc,MBc in pairs(P.mapLearn)do
if not KBc or(tonumber(MBc._at)or 0)<KBc then
JBc,KBc=LBc,tonumber(MBc._at)or 0
end
end
P.mapLearn[JBc]=nil
