local mFc={}
for nFc,oFc in ipairs(bb.mine)do
local pFc=oFc._stats.id.Value
if not V.isFarm(pFc)and not V.allyBuff(pFc)and not V.idol(pFc)and not(lFc and lFc.id==pFc)and not(bb.airLow()and bb.canAir(oFc))then
local qFc,rFc=pcall(bb.liveDps,oFc,pFc)
if qFc and rFc and rFc>0 then
table.insert(mFc,{m=oFc,dps=rFc})
end
end
end
if#mFc<3 then
return nil
end
table.sort(mFc,function(sFc,tFc)
return sFc.dps>tFc.dps
end)
local uFc=bb.ritualWorth()
if not uFc then
return mFc[3].m,dGd[3877]
end
if uFc>=1.5 then
return mFc[1].m,string.format(dGd[3878],uFc)
end
return nil
end
bb.ADAPT_ORDER={dGd[3879],dGd[3880],dGd[3881]}
function bb.adapt()
