return
end
local vFc=false
for wFc,xFc in ipairs(bb.mine or{})do
if xFc._stats.id.Value==dGd[3503]then
vFc=true
break
end
end
if not vFc then
return
end
if not(bb.adaptPrompt and bb.adaptPrompt.Parent)then
bb.adaptPrompt=nil
local yFc=M:FindFirstChild(dGd[3882])
for zFc,AFc in ipairs(yFc and yFc:GetDescendants()or{})do
if AFc.Name==dGd[3883]and not AFc:FindFirstAncestorOfClass(dGd[3884])then
bb.adaptPrompt=AFc
break
end
end
end
local BFc=bb.adaptPrompt
if not(BFc and BFc:IsA(dGd[3885])and BFc.Visible)then
bb.adaptTries=0
