end
bb.adaptTries=(bb.adaptTries or 0)+1
if bb.adaptTries>3 then
return
end
local CFc={}
for DFc,EFc in ipairs(BFc:GetDescendants())do
if EFc:IsA(dGd[3886])and EFc.Name==dGd[2515]and EFc.Parent then
CFc[EFc.Text]=EFc.Parent
end
end
for FFc,GFc in ipairs(bb.ADAPT_ORDER)do
local HFc=CFc[GFc]
local IFc=HFc and(HFc:IsA(dGd[3887])and HFc or HFc:FindFirstChildWhichIsA(dGd[3887],true))
if IFc and HFc.Visible then
local JFc=0
for KFc,LFc in ipairs({IFc.Activated,IFc.MouseButton1Click,IFc.MouseButton1Down})do
for MFc,NFc in ipairs(getconnections(LFc))do
if pcall(function()
NFc:Fire()
end)then
JFc=JFc+1
end
end
end
F.log(1,dGd[3888],string.format(dGd[3889],GFc,JFc,JFc==1 and dGd[676]or dGd[1599],bb.adaptTries))
return
end
end
end
