bb.upRate=setmetatable({},{__mode=dGd[1967]})
function bb.refund()
local RGc=N.session()
if not(bb.random and RGc)or bb.spellBusy or bb.roomPlan or not ab.every(dGd[3910],20)then
return
end
local SGc
for TGc,UGc in pairs(RGc.ingame_spells or{})do
if UGc==dGd[3896]then
SGc=TGc
end
end
if not SGc then
