end
local VGc=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local WGc=bb.bestRate or 0
if VGc or WGc<=0 then
