end
local XGc=bb.wave()
local YGc=math.max(0,(bb.total or 30)-XGc)
local ZGc=bb.mergePlan
local _Gc=bb.airLow()
local aHc,bHc,cHc
for dHc,eHc in ipairs(bb.mine)do
local fHc=eHc._stats
local gHc=fHc.id.Value
local hHc=N.Units[gHc]
local iHc=fHc:FindFirstChild(dGd[3892])and tonumber(fHc.total_spent.Value)or 0
if hHc and not hHc.unsellable and iHc>0 and not V.allyBuff(gHc)and not V.idol(gHc)and not(ZGc and ZGc.id==gHc)then
local jHc,kHc
if V.isFarm(gHc)then
local lHc=fHc:FindFirstChild(dGd[1858])and tonumber(fHc.farm_amount.Value)or 0
local mHc=lHc*YGc
if iHc>mHc*1.2 then
jHc=(iHc-mHc)*WGc
kHc=string.format(dGd[3911],U.fmt(mHc),U.fmt(iHc))
end
elseif XGc>=10 and YGc>2 and iHc>=5000 and(bb.upRate[eHc]or 0)<WGc/3 and bb.progressAt(eHc:GetPivot().Position)<0.8 and not(_Gc and bb.canAir(eHc))then
local nHc,oHc=pcall(bb.liveDps,eHc,gHc)
oHc=nHc and oHc or math.huge
if iHc*WGc>3*oHc and oHc<0.1*(bb.teamDps or 0)then
jHc=iHc*WGc-oHc
kHc=string.format(dGd[3912],U.fmt(iHc))
end
end
if jHc and(not bHc or jHc>bHc)then
aHc,bHc,cHc=eHc,jHc,kHc
end
end
end
if not aHc then
return
end
bb.spellBusy=true
task.spawn(function()
local pHc=V.name(aHc._stats.id.Value)
local qHc=F.request(dGd[3903],dGd[3904],SGc,aHc)
task.wait(1.5)
if qHc and(N.session().ingame_spells or{})[SGc]~=dGd[3896]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,dGd[3888],string.format(dGd[3913],pHc,cHc))
F.status(dGd[3782],dGd[3914]..pHc)
else
F.backoff(dGd[3903],15)
F.log(2,dGd[3888],dGd[3915]..pHc)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(rHc,sHc)
local tHc=(sHc.t or 0)-(rHc.t or 0)
if tHc<bb.BASE_WIN-1 then
return false
end
local uHc=((tonumber(rHc.base)or 0)-(tonumber(sHc.base)or 0))/tHc
if uHc<=0 or(tonumber(sHc.base)or 0)<=0 then
return false
end
local vHc=sHc.base/uHc
local wHc,xHc=0,0
local yHc,zHc=rHc.foes or{},sHc.foes or{}
for AHc,BHc in pairs(zHc)do
if BHc.prog>=bb.BASE_END then
wHc=wHc+BHc.hp
local CHc=yHc[AHc]
if CHc then
xHc=xHc+math.max(0,CHc.hp-BHc.hp)
end
end
end
for DHc,EHc in pairs(yHc)do
if EHc.prog>=bb.BASE_END and not zHc[DHc]then
xHc=xHc+EHc.hp
end
end
if wHc<=0 then
return false
end
local FHc=xHc/tHc
local GHc=FHc>0 and wHc/FHc or math.huge
local HHc={baseTime=vHc,loss=uHc,atEnd=wHc,rate=FHc,killTime=GHc}
return vHc<bb.BASE_SOON and GHc>vHc*bb.BASE_MARGIN,HHc
end
