bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(VHc)
local WHc=0
local XHc=U.flat(VHc.pos)
for YHc,ZHc in ipairs(bb.mine or{})do
local _Hc=ZHc:FindFirstChild(dGd[1813])
local aIc=_Hc and _Hc:FindFirstChild(dGd[3095])
local bIc=_Hc and _Hc:FindFirstChild(dGd[1918])
if aIc and bIc and not V.isFarm(aIc.Value)and not V.allyBuff(aIc.Value)then
local cIc,dIc=U.flat(ZHc:GetPivot().Position),bIc.Value
if(not VHc.fly or bb.canAir(ZHc))and(cIc-XHc).Magnitude>dIc then
for eIc,fIc in ipairs(bb.samples or{})do
if fIc.prog>VHc.prog and(U.flat(fIc.pos)-cIc).Magnitude<=dIc then
WHc=WHc+1
break
end
end
end
end
end
return WHc
end
function bb.leakStep(gIc)
if not gIc then
if bb.kind~=dGd[1771]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local hIc=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==dGd[1751]and P.dg.bails or{}
if not gIc and(tonumber(P.dg.bails[hIc])or 0)>=bb.BAIL_MAX then
return
end
local iIc=workspace:FindFirstChild(dGd[3916])and workspace._BASES:FindFirstChild(dGd[3482])
local jIc=iIc and iIc:FindFirstChild(dGd[3683])and iIc.base:FindFirstChild(dGd[3684])
local kIc=jIc and jIc:FindFirstChildOfClass(dGd[3504])
if not kIc or kIc.Health<=0 then
return
end
local lIc=(bb.info and tonumber(bb.info.baseRel))or fb.PRIOR.baseRel
local mIc=U.now()
bb.leakTrack=bb.leakTrack or{}
local nIc=bb.leakTrack
local oIc,pIc={},nil
for qIc,rIc in ipairs(bb.enemies or{})do
if rIc.m then
oIc[rIc.m]=true
local sIc,tIc=tonumber(rIc.hp)or 0,tonumber(rIc.prog)or 0
local uIc=nIc[rIc.m]
if not uIc then
nIc[rIc.m]={t=mIc,hp=sIc,prog=tIc}
else
if mIc-uIc.t>=bb.LEAK_WIN then
uIc.pace,uIc.net=(tIc-uIc.prog)/(mIc-uIc.t),(uIc.hp-sIc)/(mIc-uIc.t)
uIc.t,uIc.hp,uIc.prog=mIc,sIc,tIc
end
if uIc.pace and uIc.pace>0 and sIc>0 then
local vIc=(1-tIc)/uIc.pace
local wIc=math.max(0,uIc.net or 0)
local xIc=sIc-wIc*vIc
if xIc>0 and vIc<=bb.LEAK_SOON and vIc>=bb.LEAK_MIN then
local yIc=rIc.m:FindFirstChildOfClass(dGd[3504])
local zIc=kIc.Health/math.max(1,lIc*(yIc and yIc.MaxHealth or sIc))
local AIc=wIc>0 and xIc/wIc or math.huge
if AIc>zIc*bb.LEAK_MARGIN and(vIc<=bb.LEAK_AHEAD or bb.leakAhead(rIc)==0)and(not pIc or vIc<pIc.left)then
pIc={left=vIc,arriving=xIc,net=wIc,baseTime=zIc,hp=sIc}
end
end
end
end
end
end
for BIc in pairs(nIc)do
if not oIc[BIc]then
nIc[BIc]=nil
end
end
if gIc then
return pIc~=nil,pIc
end
if not pIc then
return
end
bb.bailNote(hIc)
F.log(1,dGd[2144],string.format(dGd[3919],bb.wave(),tonumber(bb.total)or 0,math.floor(pIc.left+0.5),U.fmt(pIc.hp),U.fmt(pIc.arriving),U.fmt(pIc.net),pIc.baseTime))
pcall(F.saveNow)
F.request(dGd[1821],dGd[3524])
end
