local GIc=FIc._stats
local HIc=GIc.id.Value
if not V.isFarm(HIc)and not V.allyBuff(HIc)and GIc:FindFirstChild(dGd[1918])then
local IIc=tonumber(GIc.range.Value)or 0
local JIc=bb.coverMax[FIc]
if not(JIc and JIc.r==IIc)then
local KIc,LIc=U.flat(FIc:GetPivot().Position),-1
for MIc,NIc in ipairs(bb.samples or{})do
if NIc.prog>LIc and(U.flat(NIc.pos)-KIc).Magnitude<=IIc then
LIc=NIc.prog
end
end
JIc={r=IIc,far=LIc}
bb.coverMax[FIc]=JIc
end
table.insert(DIc,{far=JIc.far,air=bb.canAir(FIc)})
end
end
if#DIc==0 then
return false
end
for OIc,PIc in ipairs(CIc)do
for QIc,RIc in ipairs(DIc)do
if(not PIc.fly or RIc.air)and RIc.far>=(tonumber(PIc.prog)or 0)then
return false
end
end
end
return true
end
